"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["41982"],{87227(e){e.exports=JSON.parse('{"id":"F428","slug":"rational-bubble-growth","name":"Rational Bubble: Required Growth and Survival","subject":"Behavioral Finance","section":"Behavioral","topic":"Bubbles and manias","level":"Intermediate","aliases":["bubbles and manias","Blanchard Watson","bubble burst probability","explosive growth"],"formula":{"latex":"g=\\\\frac{1+r}{1-\\\\pi}-1,\\\\quad P(\\\\text{survive } n)=(1-\\\\pi)^{n},\\\\quad B_{n}=B_{0}(1+g)^{n}","also":[],"text":"If a bubble bursts with probability pi each period, holders require the bubble part of the price to grow, while it survives, at g = (1 + r) / (1 - pi) - 1 so that the expected return stays at r; Chance it survives n periods = (1 - pi)^n; Bubble size after n periods if it survives = B0 x (1 + g)^n"},"symbols":[{"symbol":"r","meaning":"Required return of holders","unit":"per year"},{"symbol":"pi","meaning":"Chance per period that the bubble bursts","unit":"percent"},{"symbol":"B_0","meaning":"Size of the bubble component of the price today","unit":"money"},{"symbol":"g","meaning":"Growth rate the bubble must have to keep holders willing","unit":"per year"}],"when_to_use":"Use it to see why bubbles are explosive. A price above fundamental value can persist if holders believe it will keep rising fast enough to pay for the burst risk. The required growth is high, so the bubble component becomes large the longer it lasts, while the chance of surviving falls. It shows that a bubble can be consistent with rational expectations, not that it is likely.","worked_example":{"problem":"Holders require 8% a year. The chance of a burst each year is 10%. The bubble part of the price is 20 today.","inputs":{"r":8,"pi":10,"b":20,"n":5},"steps":[{"label":"Required growth = (1 + r) / (1 - pi) - 1","working":"(1+0.08) / (1-0.1)-1","value":"20.00%"},{"label":"Bubble size after n years if it survives","working":"20 x (1+0.2)^5","value":"49.77"},{"label":"Probability it survives n years","working":"(1-0.1)^5","value":"59.0%"},{"label":"Expected bubble size = survival chance x size","working":"0.59049 x 49.7664","value":"29.39"},{"label":"Expected size growth at r: B0 x (1 + r)^n","working":"20 x (1+0.08)^5","value":"29.39"}],"answer":"While the bubble survives it must grow 20.00% a year. After 5 years the bubble part would be 49.77, if it survives, and the chance of surviving that long is 59.0%. The expected bubble part, counting the burst risk, is 29.39, consistent with growth at the required 8%."},"calculator":{"available":true,"inputs":[{"id":"r","label":"Required return","unit":"%","type":"number","default":8,"hint":""},{"id":"pi","label":"Burst probability per year","unit":"%","type":"number","default":10,"hint":""},{"id":"b","label":"Bubble component today","unit":"money","type":"number","default":20,"hint":""},{"id":"n","label":"Years","unit":"years","type":"number","default":5,"hint":"","min":1}],"checks":[{"expr":"pi>0 and pi<1","message":"The burst probability must be between 0 and 100%."}],"steps":[{"id":"g","label":"Required growth = (1 + r) / (1 - pi) - 1","expr":"(1+r)/(1-pi)-1","format":"pct2"},{"id":"bn","label":"Bubble size after n years if it survives","expr":"b*(1+g)^n","format":"money"},{"id":"surv","label":"Probability it survives n years","expr":"(1-pi)^n","format":"pct1"},{"id":"ev","label":"Expected bubble size = survival chance x size","expr":"surv*bn","format":"money"},{"id":"chk","label":"Expected size growth at r: B0 x (1 + r)^n","expr":"b*(1+r)^n","format":"money"}],"results":["g","bn","surv","ev"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"g":0.19999999999999996,"bn":49.76639999999999,"surv":0.5904900000000001,"ev":29.386561535999995,"chk":29.38656153600001}},"finder":{"finds":"How fast a bubble must grow and how likely it is to last","needs":"Required return, burst probability, bubble size, years"},"related":[{"slug":"arbitrage-holding-cost","name":"Limits to Arbitrage: Holding Cost and Adverse Move"},{"slug":"noise-variance-share","name":"Noise Trading: Share of Price Variance Explained by Fundamentals"},{"slug":"maximum-drawdown","name":"Maximum Drawdown"}],"related_ids":["F419","F427","F250"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>g</mi><mo>=</mo><mfrac><mrow><mn>1</mn><mo>+</mo><mi>r</mi></mrow><mrow><mn>1</mn><mo>\u2212</mo><mi>\u03C0</mi></mrow></mfrac><mo>\u2212</mo><mn>1</mn><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>P</mi><mo stretchy=\\"false\\">(</mo><mtext>survive\xa0</mtext><mi>n</mi><mo stretchy=\\"false\\">)</mo><mo>=</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>\u03C0</mi><msup><mo stretchy=\\"false\\">)</mo><mi>n</mi></msup><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msub><mi>B</mi><mi>n</mi></msub><mo>=</mo><msub><mi>B</mi><mn>0</mn></msub><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>g</mi><msup><mo stretchy=\\"false\\">)</mo><mi>n</mi></msup></mrow><annotation encoding=\\"application/x-tex\\">g=\\\\frac{1+r}{1-\\\\pi}-1,\\\\quad P(\\\\text{survive } n)=(1-\\\\pi)^{n},\\\\quad B_{n}=B_{0}(1+g)^{n}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"fed-funds-futures-probability","name":"Rate Expectations from Policy Rate Futures"},"next":{"slug":"news-move-significance","name":"Reading the News: Is This Move Unusual?"},"lesson":null,"total":522}')}}]);